// clone path with spaces (test/commands/builder_test.rb:229)
func TestBuilderClonePathWithSpaces(t *testing.T) {
	c := newBuilderCase(t)
	c.results["git rev-parse --show-toplevel"] = gitResult("/absolute/path with spaces")
	builder := c.builder(t)
	clone, err := builder.Clone()
	if err != nil {
		t.Fatal(err)
	}
	steps, err := builder.CloneResetSteps()
	if err != nil {
		t.Fatal(err)
	}
	for _, line := range append([]Line{clone}, steps...) {
		assertMatch(t, `path\\ with\\ space`, line.String())
		assertNoMatch(t, `path with spaces`, line.String())
	}
}

// clone reset runs git gc --auto to bound pack growth (test/commands/builder_test.rb:244)
func TestBuilderCloneResetRunsGitGcAutoToBoundPackGrowth(t *testing.T) {
	c := newBuilderCase(t)
	steps, err := c.builder(t).CloneResetSteps()
	if err != nil {
		t.Fatal(err)
	}
	if last := steps[len(steps)-1].String(); !strings.HasSuffix(last, " gc --auto --quiet") {
		t.Fatalf("expected clone_reset_steps to run git gc --auto, got: %q", last)
	}
}

